            });
        }
        if budget.pays_allocations() {
            budget.reserve_bytes(function, Self::COLD_ROOT_CONTROLS, "factored cold terminal root predicate")?;
        }
        if root.len() == 1 && root[0].1 == 1 && self.cold_dead_node(root[0].0) {
